{
  "id": "app-mvxx957p",
  "name": "What's for dinner",
  "description": "What's for dinner: I type what's in my fridge, Meta's model suggests three dinners I can cook in 30 minutes with short steps, and I can save the ones I like to a favorites list.",
  "theme": {
    "accent": "#E86A33"
  },
  "capabilities": [
    "ai"
  ],
  "data": {
    "favorites": {
      "type": "list",
      "fields": {
        "id": {
          "type": "string"
        },
        "title": {
          "type": "string"
        },
        "time": {
          "type": "string"
        },
        "ingredients": {
          "type": "list"
        },
        "steps": {
          "type": "list"
        }
      }
    }
  },
  "state": {
    "fridgeInput": "",
    "suggestions": [],
    "busy": false,
    "err": ""
  },
  "start": "main",
  "screens": {
    "main": {
      "title": "What's for dinner",
      "scroll": true,
      "body": {
        "type": "column",
        "style": {
          "padding": 16,
          "gap": 12
        },
        "children": [
          {
            "type": "text",
            "variant": "body",
            "value": "Type what's in your fridge, get 3 dinners you can cook in 30 minutes.",
            "style": {
              "color": "muted"
            }
          },
          {
            "type": "textfield",
            "placeholder": "e.g. chicken, rice, broccoli, eggs",
            "bind": "fridgeInput"
          },
          {
            "type": "button",
            "label": "{{busy ? 'Thinking…' : 'Get 3 dinners'}}",
            "variant": "primary",
            "onTap": [
              {
                "set": "err",
                "to": ""
              },
              {
                "if": "trim(fridgeInput) == ''",
                "then": [
                  {
                    "set": "err",
                    "to": "'Tell me what is in your fridge first.'"
                  }
                ],
                "else": [
                  {
                    "set": "busy",
                    "to": true
                  },
                  {
                    "ask": {
                      "prompt": "{{'Suggest exactly 3 dinners I can cook in 30 minutes or less using mostly: ' + fridgeInput + '. For each give a short title, total time like 20 min, key ingredients, and 3-5 very short steps. Prefer what I have, add only common pantry staples.'}}",
                      "system": "{{'You suggest quick 30-minute dinners using what is in the fridge plus common staples. Be practical and concise.'}}",
                      "schema": {
                        "type": "object",
                        "properties": {
                          "meals": {
                            "type": "array",
                            "minItems": 3,
                            "maxItems": 3,
                            "items": {
                              "type": "object",
                              "properties": {
                                "title": {
                                  "type": "string"
                                },
                                "time": {
                                  "type": "string"
                                },
                                "ingredients": {
                                  "type": "array",
                                  "items": {
                                    "type": "string"
                                  }
                                },
                                "steps": {
                                  "type": "array",
                                  "items": {
                                    "type": "string"
                                  }
                                }
                              },
                              "required": ["title", "time", "ingredients", "steps"]
                            }
                          }
                        },
                        "required": ["meals"]
                      },
                      "effort": "low",
                      "maxTokens": 1500
                    },
                    "then": [
                      {
                        "set": "busy",
                        "to": false
                      },
                      {
                        "set": "suggestions",
                        "to": "value.meals"
                      }
                    ],
                    "else": [
                      {
                        "set": "busy",
                        "to": false
                      },
                      {
                        "set": "err",
                        "to": "error"
                      }
                    ]
                  }
                ]
              }
            ]
          },
          {
            "type": "text",
            "variant": "caption",
            "value": "{{err}}",
            "if": "err != ''",
            "style": {
              "color": "danger"
            }
          },
          {
            "type": "text",
            "variant": "caption",
            "value": "Finding ideas…",
            "if": "busy",
            "style": {
              "color": "muted"
            }
          },
          {
            "type": "column",
            "each": "suggestions",
            "as": "s",
            "style": {
              "gap": 12
            },
            "children": [
              {
                "type": "card",
                "children": [
                  {
                    "type": "text",
                    "variant": "headline",
                    "value": "{{s.title}}"
                  },
                  {
                    "type": "text",
                    "variant": "caption",
                    "value": "{{s.time}}",
                    "style": {
                      "color": "muted"
                    }
                  },
                  {
                    "type": "text",
                    "variant": "caption",
                    "value": "Ingredients",
                    "style": {
                      "fontWeight": "bold",
                      "marginTop": 6
                    }
                  },
                  {
                    "type": "text",
                    "variant": "body",
                    "value": "{{join(s.ingredients, ', ')}}"
                  },
                  {
                    "type": "text",
                    "variant": "caption",
                    "value": "Steps",
                    "style": {
                      "fontWeight": "bold",
                      "marginTop": 6
                    }
                  },
                  {
                    "type": "column",
                    "each": "s.steps",
                    "as": "st",
                    "indexAs": "idx",
                    "style": {
                      "gap": 2
                    },
                    "children": [
                      {
                        "type": "text",
                        "variant": "callout",
                        "value": "{{(idx+1) + '. ' + st}}"
                      }
                    ]
                  },
                  {
                    "type": "button",
                    "label": "Save to favorites",
                    "variant": "secondary",
                    "style": {
                      "marginTop": 8
                    },
                    "onTap": {
                      "push": "favorites",
                      "value": {
                        "id": "uid()",
                        "title": "s.title",
                        "time": "s.time",
                        "ingredients": "s.ingredients",
                        "steps": "s.steps"
                      }
                    }
                  }
                ]
              }
            ]
          },
          {
            "type": "divider"
          },
          {
            "type": "row",
            "style": {
              "justify": "between",
              "align": "center"
            },
            "children": [
              {
                "type": "text",
                "variant": "headline",
                "value": "{{'Favorites (' + len(favorites) + ')'}}"
              },
              {
                "type": "button",
                "label": "View all",
                "variant": "plain",
                "onTap": {
                  "navigate": "favorites"
                }
              }
            ]
          },
          {
            "type": "text",
            "variant": "caption",
            "value": "No favorites yet — tap Save on a dinner you like.",
            "if": "len(favorites) == 0",
            "style": {
              "color": "muted"
            }
          },
          {
            "type": "list",
            "items": "slice(favorites, 0, 3)",
            "as": "fav",
            "variant": "inset",
            "row": {
              "type": "column",
              "children": [
                {
                  "type": "text",
                  "variant": "headline",
                  "value": "{{fav.title}}"
                },
                {
                  "type": "text",
                  "variant": "caption",
                  "value": "{{fav.time + ' • ' + join(fav.ingredients, ', ')}}",
                  "style": {
                    "color": "muted"
                  }
                }
              ]
            }
          }
        ]
      }
    },
    "favorites": {
      "title": "Favorites",
      "scroll": true,
      "body": {
        "type": "column",
        "style": {
          "padding": 16,
          "gap": 12
        },
        "children": [
          {
            "type": "text",
            "variant": "caption",
            "value": "Your saved dinners.",
            "style": {
              "color": "muted"
            }
          },
          {
            "type": "list",
            "items": "favorites",
            "as": "fav",
            "variant": "inset",
            "empty": "No favorites yet. Go back and save one you like.",
            "swipe": [
              {
                "label": "Delete",
                "do": {
                  "remove": "fav"
                }
              }
            ],
            "row": {
              "type": "column",
              "style": {
                "gap": 4,
                "paddingY": 4
              },
              "children": [
                {
                  "type": "text",
                  "variant": "headline",
                  "value": "{{fav.title}}"
                },
                {
                  "type": "text",
                  "variant": "caption",
                  "value": "{{fav.time}}",
                  "style": {
                    "color": "muted"
                  }
                },
                {
                  "type": "text",
                  "variant": "callout",
                  "value": "{{join(fav.ingredients, ', ')}}"
                },
                {
                  "type": "column",
                  "each": "fav.steps",
                  "as": "fs",
                  "indexAs": "fi",
                  "children": [
                    {
                      "type": "text",
                      "variant": "callout",
                      "value": "{{(fi+1) + '. ' + fs}}",
                      "style": {
                        "color": "muted"
                      }
                    }
                  ]
                }
              ]
            }
          },
          {
            "type": "button",
            "label": "Find more dinners",
            "variant": "secondary",
            "onTap": {
              "back": true
            }
          }
        ]
      }
    }
  }
}
```","type":"response.output_text.done"}

